cat >> wfm/constraints.py <<'EOF'


# ---- queue staffing hours and infeasible intervals (Litware SOW §2.5, §2.6) ------------------------
#
#     queue_staff_hours:            # local hours in which agents may be scheduled on a queue
#       email: [9, 21]              # (default: the operating hours)
#     infeasible_intervals: report  # mark intervals the rules make impossible; see `infeasible`
#
# Both are optional; leaving them out keeps the service behaviour.

def staff_hours(cfg: dict, queue: str) -> tuple[float, float]:
    lo, hi = (cfg.get("queue_staff_hours") or {}).get(queue, cfg["operating_hours"])
    return float(lo), float(hi)


def staffable(cfg: dict, queue: str, segments) -> bool:
    """True if every local (start_hour, end_hour) segment lies inside the queue's staffing hours."""
    lo, hi = staff_hours(cfg, queue)
    return all(lo <= s and e <= hi for s, e in segments)


def infeasible(req, cfg: dict, agents) -> set:
    """(queue, interval_start_utc) pairs whose target the scheduling rules make impossible to meet
    (Litware SOW §2.6), for clients with `infeasible_intervals: report`; empty otherwise.

    An interval is infeasible when it needs staff (`required` > 0) and either no agent may be scheduled
    on the queue at that time (outside `queue_staff_hours`), or the requirement exceeds the number of
    agents in the roster who hold the queue's skill."""
    if cfg.get("infeasible_intervals") != "report":
        return set()
    z = ZoneInfo(cfg["tz"])
    skilled = {q: sum(1 for a in agents if q in a.skills) for q in set(req["queue"])}
    out = set()
    for r in req.itertuples(index=False):
        if int(r.required) <= 0:
            continue
        loc = r.interval_start_utc.astimezone(z)
        h = loc.hour + loc.minute / 60
        lo, hi = staff_hours(cfg, r.queue)
        if not (lo <= h < hi) or int(r.required) > skilled[r.queue]:
            out.add((r.queue, r.interval_start_utc))
    return out
EOF

